/**
 * PDF Font Configuration for Unicode Support
 *
 * jsPDF's default fonts (Helvetica, Times, Courier) do not support Myanmar/Burmese Unicode characters.
 * To enable Myanmar font support, you need to:
 *
 * 1. Download a Myanmar Unicode font (e.g., Noto Sans Myanmar from Google Fonts)
 * 2. Convert the .ttf file to base64 using: https://products.aspose.app/font/base64
 * 3. Add the font to jsPDF using addFileToVFS and addFont
 *
 * INSTRUCTIONS TO ADD MYANMAR FONT SUPPORT:
 * ============================================
 *
 * Step 1: Download Noto Sans Myanmar
 * - Visit: https://fonts.google.com/noto/specimen/Noto+Sans+Myanmar
 * - Download the font (NotoSansMyanmar-Regular.ttf)
 *
 * Step 2: Convert to Base64
 * - Go to: https://products.aspose.app/font/base64
 * - Upload NotoSansMyanmar-Regular.ttf
 * - Copy the base64 string (it will be very long)
 *
 * Step 3: Add to this file
 * - Uncomment the code below and paste the base64 string
 *
 * Step 4: Use in invoiceGenerator.js
 * - The setupMyanmarFont function will be automatically called
 */

// UNCOMMENT AND REPLACE WITH ACTUAL BASE64 FONT DATA:
export const NotoSansMyanmar = '';

/**
 * Setup Myanmar font in jsPDF document
 * @param {jsPDF} doc - jsPDF document instance
 */
export const setupMyanmarFont = (doc) => {
  try {
    // Check if font data is available
    // Uncomment this when you have the base64 font:
    if (typeof NotoSansMyanmar !== 'undefined') {
      doc.addFileToVFS('NotoSansMyanmar-Regular.ttf', NotoSansMyanmar);
      doc.addFont('NotoSansMyanmar-Regular.ttf', 'NotoSansMyanmar', 'normal');
      return true; // Font loaded successfully
    }
    return false; // Font not available
  } catch (error) {
    console.error('Failed to load Myanmar font:', error);
    return false;
  }
};

/**
 * Check if text contains Myanmar characters
 * @param {string} text - Text to check
 * @returns {boolean}
 */
export const containsMyanmarText = (text) => {
  if (!text) return false;
  // Myanmar Unicode range: U+1000 to U+109F
  const myanmarRegex = /[\u1000-\u109F]/;
  return myanmarRegex.test(text);
};

/**
 * Get appropriate font for text
 * @param {string} text - Text to check
 * @param {boolean} fontAvailable - Whether Myanmar font is loaded
 * @returns {string} Font name to use
 */
export const getFontForText = (text, fontAvailable) => {
  if (containsMyanmarText(text) && fontAvailable) {
    return 'NotoSansMyanmar';
  }
  return 'helvetica';
};

// ALTERNATIVE SOLUTION: Generate PDF on backend
// For production use with Myanmar text, consider generating PDFs on the backend using:
// - Node.js with 'pdfkit' library (better Unicode support)
// - Puppeteer (renders HTML to PDF with full browser font support)
// - wkhtmltopdf (command-line tool with excellent Unicode support)

export default {
  setupMyanmarFont,
  containsMyanmarText,
  getFontForText,
};
